"NodeA": {
"recognition": "OCR",    // Recognition algorithm
"action": "Click",       // Action to be executed
"next": [                // List of subsequent nodes
"NodeB",
"NodeC"
],
// Other extended properties...
},
// Other node definitions...
}
```

